#include "driver.hpp"
#include <cstdio>
#include <iostream>
#include <map>
#include <stdexcept>
#include "diff.hpp"
#include "files.hpp"

#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif

namespace {
	void write_out(std::string const& text)
	{
#ifdef _WIN32
		_setmode(_fileno(stdout), _O_BINARY);
#endif
		std::fwrite(text.data(), 1, text.size(), stdout);
		std::fflush(stdout);
	}

	void merge(blitz::tools::settings& into, blitz::tools::settings const& from)
	{
		into.insert(into.end(), from.begin(), from.end()); // Later entries win, the tools apply them in order.
	}
} // namespace

int blitz::tools::run(driver const& tool, int argc, char** argv)
{
	bool                     in_place = false, recursive = false, check = false, diff = false, quiet = false, no_config = false, print_config = false;
	std::filesystem::path    config_file;
	std::string              stdin_name = "<stdin>";
	bool                     stdin_named = false;
	settings                 cli;
	std::vector<std::string> files;

	for (int i = 1; i < argc; i++) {
		std::string arg = argv[i];
		if ((arg == "-h") || (arg == "--help")) {
			std::cout << tool.name << " - " << tool.summary << "\n\n"
					  << "Usage: " << tool.name << " [options] [file...]\n\n"
					  << "Without files, or with -, the standard input is read and the result written to the standard output.\n\n"
					  << "  -i, --in-place          rewrite the files\n"
					  << "      --check             list the files that would change, exit 1 if there are any\n"
					  << "      --diff              show a unified diff of the changes, exit 1 if there are any\n"
					  << "  -r, --recursive         use every .bb, .b3d and .bp file beneath the directories that are given\n"
					  << "  -q, --quiet             no messages except errors\n"
					  << "      --config=FILE       use this configuration file instead of the nearest one\n"
					  << "      --no-config         ignore configuration files\n"
					  << "      --stdin-filepath=P  the name of stdin, for messages and for finding the configuration file\n"
					  << "      --print-config      show the settings that would be used\n"
					  << "      --KEY=VALUE         a setting (--KEY alone is true, --no-KEY is false) that overrides the configuration file\n"
					  << "  -v, --version           show the version\n\n"
					  << "The settings are read from " << tool.config_names[0];
			for (size_t n = 1; n < tool.config_names.size(); n++) {
				std::cout << " or " << tool.config_names[n];
			}
			std::cout << " in the directory of the file or the nearest parent directory.\n\n"
					  << tool.options_help;
			return 0;
		} else if ((arg == "-v") || (arg == "--version")) {
			std::cout << tool.name << " " << tool.version << "\n";
			return 0;
		} else if ((arg == "-i") || (arg == "--in-place")) {
			in_place = true;
		} else if ((arg == "-r") || (arg == "--recursive")) {
			recursive = true;
		} else if (arg == "--check") {
			check = true;
		} else if (arg == "--diff") {
			diff = true;
		} else if ((arg == "-q") || (arg == "--quiet")) {
			quiet = true;
		} else if (arg == "--no-config") {
			no_config = true;
		} else if (arg == "--print-config") {
			print_config = true;
		} else if (arg.rfind("--config=", 0) == 0) {
			config_file = arg.substr(9);
		} else if (arg.rfind("--stdin-filepath=", 0) == 0) {
			stdin_name  = arg.substr(17);
			stdin_named = true;
		} else if (arg == "-") {
			files.push_back(arg);
		} else if (arg.rfind("--", 0) == 0) {
			std::string body = arg.substr(2);
			size_t      eq   = body.find('=');
			if (eq != std::string::npos) {
				cli.emplace_back(normalize_key(body.substr(0, eq)), body.substr(eq + 1));
			} else if (body.rfind("no-", 0) == 0) {
				cli.emplace_back(normalize_key(body.substr(3)), "false");
			} else {
				cli.emplace_back(normalize_key(body), "true");
			}
		} else if ((arg.size() > 1) && (arg[0] == '-')) {
			std::cerr << tool.name << ": Unknown option '" << arg << "'. See --help.\n";
			return 2;
		} else {
			files.push_back(arg);
		}
	}

	if (in_place && (files.empty() || (files == std::vector<std::string>{ "-" }))) {
		std::cerr << tool.name << ": --in-place needs files.\n";
		return 2;
	}
	if (files.empty()) {
		files.push_back("-");
	}

	// A directory is every source file beneath it with -r, and a mistake without.
	{
		std::vector<std::string> expanded;
		for (auto const& file : files) {
			std::error_code ec;
			if ((file != "-") && std::filesystem::is_directory(file, ec)) {
				if (!recursive) {
					std::cerr << tool.name << ": " << file << ": is a directory, use -r to process the files beneath it.\n";
					return 2;
				}
				try {
					for (auto const& found : find_sources(file)) {
						expanded.push_back(found.generic_string());
					}
				} catch (std::exception const& ex) {
					std::cerr << tool.name << ": " << ex.what() << "\n";
					return 2;
				}
			} else {
				expanded.push_back(file);
			}
		}
		files = expanded;
		if (files.empty()) {
			return 0; // Directories without sources
		}
	}

	std::map<std::filesystem::path, settings> cache;
	auto settings_for = [&](std::filesystem::path const& directory) -> settings {
		settings out;
		if (no_config) {
			merge(out, cli);
			return out;
		}
		std::filesystem::path path = config_file;
		if (path.empty()) {
			auto found = find_config(directory, tool.config_names);
			if (found) {
				path = *found;
			}
		}
		if (!path.empty()) {
			auto it = cache.find(path);
			if (it == cache.end()) {
				it = cache.emplace(path, load_config(path)).first;
			}
			merge(out, it->second);
		}
		merge(out, cli);
		return out;
	};

	int  exit_code = 0;
	bool changed   = false;
	for (auto const& file : files) {
		bool        is_stdin = (file == "-");
		std::string name     = is_stdin ? stdin_name : file;
		try {
			std::filesystem::path directory = is_stdin ? (stdin_named ? std::filesystem::path(stdin_name).parent_path() : std::filesystem::path()) : std::filesystem::path(file).parent_path();
			if (directory.empty()) {
				directory = std::filesystem::current_path();
			}
			auto values = settings_for(directory);
			if (print_config) {
				write_out(tool.print_config ? tool.print_config(values) : std::string());
				return 0;
			}

			std::string text   = is_stdin ? read_stdin() : read_file(file);
			std::string result = tool.process(text, values, name);
			bool        differs = (result != text);
			changed |= differs;

			if (diff) {
				write_out(unified_diff(text, result, "a/" + name, "b/" + name));
			} else if (check) {
				if (differs) {
					write_out(name + "\n");
				}
			} else if (in_place) {
				if (differs) {
					write_file(file, result);
					if (!quiet) {
						std::cerr << tool.name << ": " << name << "\n";
					}
				}
			} else {
				write_out(result);
			}
		} catch (std::exception const& ex) {
			std::cerr << tool.name << ": " << name << ": " << ex.what() << "\n";
			exit_code = 2;
		}
	}
	if (exit_code == 0 && changed && (check || diff)) {
		exit_code = 1;
	}
	return exit_code;
}
